(439, 1, '2025-10-04 12:53:04', '2025-10-04 12:53:04', 'function cdnss_custom_search_bar() {\r\n    ob_start(); ?>\r\n    \r\n    <style>\r\n    .custom-search-box {\r\n      position: relative;\r\n      width: 100%;\r\n    }\r\n\r\n    .custom-search-box input[type=\"search\"] {\r\n      width: 100%;\r\n      padding: 10px 15px 10px 40px;\r\n      border: 1px solid #dcdcdc;\r\n      border-radius: 15px;\r\n      font-size: 14px;\r\n      outline: none;\r\n      transition: all 0.3s ease;\r\n    }\r\n\r\n    .custom-search-box input[type=\"search\"]:focus {\r\n      border-color: #005C99;\r\n      box-shadow: 0 0 5px rgba(0,92,153,0.3);\r\n    }\r\n\r\n    .custom-search-box svg {\r\n      position: absolute;\r\n      top: 50%;\r\n      left: 12px;\r\n      transform: translateY(-50%);\r\n      width: 16px;\r\n      height: 16px;\r\n      stroke: #888;\r\n    }\r\n    </style>\r\n\r\n    <div class=\"custom-search-box\">\r\n      <form action=\"/\" method=\"get\" role=\"search\">\r\n        <svg xmlns=\"http://www.w3.org/2000/svg\" fill=\"none\" viewBox=\"0 0 24 24\" stroke-width=\"2\">\r\n          <circle cx=\"11\" cy=\"11\" r=\"7\"/>\r\n          <line x1=\"16\" y1=\"16\" x2=\"21\" y2=\"21\"/>\r\n        </svg>\r\n        <input type=\"search\" name=\"s\" placeholder=\"Rechercher...\" class=\"searchwp-live-search\" />\r\n      </form>\r\n    </div>\r\n    \r\n    <?php\r\n    return ob_get_clean();\r\n}\r\nadd_shortcode(\'cdnss_search\', \'cdnss_custom_search_bar\');\r\n', 'top container search input', '', 'publish', 'closed', 'closed', '', 'top-container-search-input', '', '', '2025-10-18 16:34:16', '2025-10-18 16:34:16', '', 0, 'http://localhost:8080/wpcode/top-container-search-input/', 0, 'wpcode', '', 0),
