(814, 1, '2025-12-02 14:40:33', '2025-12-02 14:40:33', 'document.addEventListener(\"DOMContentLoaded\", function () {\r\n\r\n    const data = {\r\n        \"Systèmes de santé\": [\r\n            \"Qualité des soins\", \"Sécurité transfusionnelle\", \"Recherche\", \"Essais cliniques\",\r\n            \"Santé numérique\", \"Système d’information sanitaire\", \"Couverture sanitaire universelle\",\r\n            \"Economie de la santé\", \"Urgences et soins intensifs\", \"Comptes nationaux de la santé\",\r\n            \"Financement de la santé\", \"Lois sur la santé\", \"Gouvernance\", \"Hôpitaux\",\r\n            \"Prévention et contrôle des infections\", \"Soins infirmiers et obstétriques\",\r\n            \"Soins de santé primaires\", \"Génomique\",\r\n            \"Produits médicaux de qualité inférieure et falsifiés\"\r\n        ],\r\n\r\n        \"Maladies Transmissibles\": [\r\n            \"VIH/SIDA\", \"IST\", \"Tuberculose\", \"Paludisme\", \"Hépatites virales\",\r\n            \"Coronavirus\", \"Ebola\", \"Méningites\", \"Marburg\", \"Fièvre jaune\"\r\n        ],\r\n\r\n        \"Maladies évitables par la vaccination\": [\r\n            \"Tuberculose\", \"Poliomyélite\", \"Diphtérie\", \"Tétanos\", \"Coqueluche\",\r\n            \"Hépatite virale B\", \"Infection à Hemophilus type B\",\r\n            \"Infection à pneumocoque\", \"Diarrhée à Rotavirus\",\r\n            \"Fièvre jaune\", \"Rougeole\", \"Rubéole\", \"HPV\"\r\n        ],\r\n\r\n        \"Maladies Tropicales Négligées\": [\r\n            \"Onchocercose\", \"Schistosomiase\", \"Helminthiases\",\r\n            \"Filariose lymphatique\", \"Trachome\",\r\n            \"Trypanosomiase Humaine Africaine\", \"Ulcère de Buruli\",\r\n            \"Leishmaniose\", \"Pian\", \"Lèpre\"\r\n        ],\r\n\r\n        \"Maladies non transmissibles\": [\r\n            \"Cancer\", \"Hypertension\", \"Diabète\", \"Maladies rénales chroniques\",\r\n            \"Asthme\", \"Affections respiratoires chroniques\",\r\n            \"Affections buccodentaires\", \"Epilepsie\", \"Drépanocytose\",\r\n            \"Traumatismes\", \"Intoxications\"\r\n        ],\r\n\r\n        \"Maladie et affections\": [\r\n            \"Paludisme\", \"Malnutrition\", \"Maladies d’origine alimentaire\",\r\n            \"Maladies cardiovasculaires\", \"Infections sexuellement transmissibles\",\r\n            \"Choléra\", \"Mpox\", \"Chikungunya\"\r\n        ],\r\n\r\n        \"Health interventions\": [\r\n            \"Nutrition infantile\", \"Allaitement maternel\", \"Alimentation complémentaire\",\r\n            \"Vaccins et vaccination\", \"Médicaments\", \"Avortement\", \"Transplantation\",\r\n            \"One health\", \"Contraception\"\r\n        ],\r\n\r\n        \"Environnement physique\": [\r\n            \"Résistance aux antimicrobiens\", \"Santé environnementale\",\r\n            \"Sécurité sanitaire des aliments\", \"Pollution atmosphérique\", \"WASH\"\r\n        ],\r\n\r\n        \"Déterminants sociopolitiques\": [\r\n            \"Santé urbaine\", \"Déterminants sociaux de la santé\", \"Infodémie\",\r\n            \"Règlement Sanitaire International\", \"Déterminants commerciaux de la santé\",\r\n            \"Développement durable\", \"Santé et genre\", \"Global health ethics\",\r\n            \"Droits humains\", \"Sécurité sanitaire\", \"Propriété intellectuelle\"\r\n        ],\r\n\r\n        \"Populations et démographie\": [\r\n            \"Santé des adolescents\", \"Santé de l’enfant\", \"Santé maternelle\",\r\n            \"Santé du nouveau-né\", \"Santé des réfugiés et des migrants\",\r\n            \"Vieillissement\", \"Handicap\"\r\n        ],\r\n\r\n        \"Comportement humain\": [\r\n            \"Nutrition\", \"Comportement addictif\",\r\n            \"Mutilations génitales féminines\",\r\n            \"Violence à l’encontre des femmes\",\r\n            \"Violence envers les enfants\",\r\n            \"Interventions d’auto-prise en charge\"\r\n        ],\r\n\r\n        \"Conditions\": [\"Obésité\", \"Mortinaissances\", \"Dépression\"],\r\n\r\n        \"Santé et bien-être\": [\"Santé sexuelle\", \"Santé mentale\", \"Croissance de l’enfant\"],\r\n\r\n        \"Substances\": [\"Tabagisme\", \"Radon\", \"Micronutriments\"],\r\n\r\n        \"Interventions physiologiques\": [\"Produits sanguins\"],\r\n\r\n        \"Blessures\": [\"Accidents de la voie publique\", \"Noyade\"],\r\n\r\n        \"Catastrophes\": [\r\n            \"Accidents chimiques\", \"Changement climatique\", \"Tremblements de terre\",\r\n            \"Inondations\", \"Glissements de terrain\", \"Sécheresse\",\r\n            \"Urgences radiologiques\", \"Tsunamis\",\r\n            \"Éruptions volcaniques\", \"Feux de forêt\"\r\n        ],\r\n\r\n        \"Interventions comportementales\": [\"Promotion de la santé\"],\r\n\r\n        \"Autres\": [\"Equité en santé\", \"Santé et énergie\", \"Alcool\"]\r\n    };\r\n\r\n\r\n    /** \r\n     * Because Elementor forms load dynamically,\r\n     * we detect them using a delegated event and jQuery.\r\n     */\r\n    jQuery(document).on(\"elementor/frontend/init elementor/popup/show\", function () {\r\n\r\n        jQuery(\'.elementor-form\').each(function () {\r\n\r\n            const form = jQuery(this);\r\n\r\n            const themeField = form.find(\'[name=\"form_fields[theme]\"]\');\r\n            const subThemeField = form.find(\'[name=\"form_fields[subtheme]\"]\');\r\n\r\n            if (!themeField.length || !subThemeField.length) return;\r\n\r\n            themeField.on(\"change\", function () {\r\n                const selected = jQuery(this).val();\r\n\r\n                // Clear SubTheme options\r\n                subThemeField.html(\"\");\r\n\r\n                if (data[selected]) {\r\n                    data[selected].forEach(item => {\r\n                        subThemeField.append(\r\n                            `<option value=\"${item}\">${item}</option>`\r\n                        );\r\n                    });\r\n                }\r\n            });\r\n\r\n        });\r\n\r\n    });\r\n\r\n});\r\n', 'Dynamic SubTheme select options', '', 'publish', 'closed', 'closed', '', 'dynamic-subtheme-select-options', '', '', '2025-12-02 15:43:51', '2025-12-02 15:43:51', '', 0, 'http://localhost/wpcode/dynamic-subtheme-select-options/', 0, 'wpcode', '', 0),
